class A {
protected:
    int v;
public:
    A(int n=0): v(n) {}
    virtual int get_value() { return v; }
    A* operator->() { return this; }
    A& operator+(A* p) { v += p->v; return *this; }
};
class B : public A {
public:
    B(int n): A(n) {}
};
class C : public A {
